// Browser-local DataFrame operations. No code evaluation and no network requests.
export const missing=v=>v===null||v===undefined||v==='';
export const numeric=v=>typeof v==='number'&&Number.isFinite(v);
export function scalar(v){if(typeof v!=='string')return v;v=v.trim();if(!v)return null;if(/^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?$/.test(v)&&Number.isFinite(Number(v)))return Number(v);return v;}
export function parseCSV(text,delimiter=','){
 text=text.replace(/^\uFEFF/,'');let rows=[],row=[],cell='',quoted=false;
 for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(quoted){quoted=false;}else if(cell===''){quoted=true;}else cell+=c;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell='';}else cell+=c;}
 if(quoted)throw Error('CSV_QUOTE');if(cell!==''||row.length){row.push(cell);if(row.some(x=>x!==''))rows.push(row);}if(rows.length<2)throw Error('EMPTY');
 const cols=rows.shift().map(x=>x.trim());if(cols.some(x=>!x)||new Set(cols).size!==cols.length)throw Error('HEADERS');
 if(rows.some(r=>r.length!==cols.length))throw Error('CSV_WIDTH');
 return validate(rows.map(r=>Object.fromEntries(cols.map((c,i)=>[c,scalar(r[i])]))));
}
export function validate(rows){if(!Array.isArray(rows)||!rows.length)throw Error('EMPTY');if(rows.length>20000)throw Error('LIMIT');if(rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('JSON_ROWS');const cols=[...new Set(rows.flatMap(Object.keys))];if(!cols.length||cols.length>80)throw Error('LIMIT');if(cols.some(c=>!c.trim()))throw Error('HEADERS');return rows.map(r=>Object.fromEntries(cols.map(c=>{let v=r[c]??null;if(v!==null&&(typeof v==='object'||(typeof v==='number'&&!Number.isFinite(v))))throw Error('JSON_NESTED');return[c,v];})));}
export function columns(rows){return rows.length?Object.keys(rows[0]):[];}
export function profile(rows,cols=columns(rows)){return cols.map(key=>{const vals=rows.map(r=>r[key]).filter(v=>!missing(v));return{key,type:vals.length&&vals.every(numeric)?'number':vals.length&&vals.every(v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}/.test(v)&&!Number.isNaN(Date.parse(v)))?'date':'text',missing:rows.length-vals.length,unique:new Set(vals).size};});}
export function quantile(sorted,q){if(!sorted.length)return null;let p=(sorted.length-1)*q,i=Math.floor(p);return sorted[i]+(sorted[Math.ceil(p)]-sorted[i])*(p-i);}
export function describe(values){let v=values.filter(numeric).sort((a,b)=>a-b),n=v.length;if(!n)return{count:0,mean:null,std:null,min:null,q1:null,median:null,q3:null,max:null,sum:0};let sum=v.reduce((a,b)=>a+b,0),mean=sum/n;return{count:n,mean,std:n>1?Math.sqrt(v.reduce((a,b)=>a+(b-mean)**2,0)/(n-1)):null,min:v[0],q1:quantile(v,.25),median:quantile(v,.5),q3:quantile(v,.75),max:v[n-1],sum};}
export function aggregate(rows,key,fn){let vals=rows.map(r=>r[key]);if(fn==='count')return vals.filter(v=>!missing(v)).length;let s=describe(vals);return s[fn]??null;}
export function groupBy(rows,key,value,fn='sum',month=false){const map=new Map();for(const r of rows){let v=r[key];if(month&&!missing(v))v=String(v).slice(0,7);const k=JSON.stringify(v??null);if(!map.has(k))map.set(k,{key:v,rows:[]});map.get(k).rows.push(r);}return [...map.values()].map(g=>({key:g.key,value:aggregate(g.rows,value,fn),count:g.rows.length}));}
export function filterRows(rows,key,op,value){return rows.filter(r=>{const v=r[key];if(op==='missing')return missing(v);if(op==='present')return !missing(v);if(missing(v))return false;if(op==='contains')return String(v).toLowerCase().includes(String(value).toLowerCase());if(op==='eq')return String(v)===String(value);if(op==='ne')return String(v)!==String(value);if(op==='gt')return numeric(v)&&v>Number(value);if(op==='lt')return numeric(v)&&v<Number(value);if(op==='gte')return numeric(v)&&v>=Number(value);if(op==='lte')return numeric(v)&&v<=Number(value);return true;});}
export function sortRows(rows,key,dir='asc'){return [...rows].sort((a,b)=>{if(missing(a[key]))return missing(b[key])?0:1;if(missing(b[key]))return-1;const n=numeric(a[key])&&numeric(b[key])?a[key]-b[key]:String(a[key]).localeCompare(String(b[key]),undefined,{numeric:true});return dir==='desc'?-n:n;});}
export function dedupe(rows,cols=columns(rows)){const seen=new Set();return rows.filter(r=>{let k=JSON.stringify(cols.map(c=>r[c]));if(seen.has(k))return false;seen.add(k);return true;});}
export function fillMissing(rows,key,method,custom){let value=method==='custom'?scalar(custom):describe(rows.map(r=>r[key]))[method];if(value===null||value===undefined)throw Error('NO_NUMERIC');return rows.map(r=>missing(r[key])?{...r,[key]:value}:r);}
export function compute(rows,name,a,op,b,constant){if(!name.trim()||columns(rows).includes(name))throw Error('COLUMN_NAME');return rows.map(r=>{let x=r[a],y=constant!==undefined?Number(constant):r[b];let z=null;if(numeric(x)&&numeric(y)){z=op==='+'?x+y:op==='-'?x-y:op==='*'?x*y:y===0?null:x/y;if(!Number.isFinite(z))z=null;}return{...r,[name]:z};});}
export function pivot(rows,rowKey,colKey,val,fn){let keys=[...new Set(rows.map(r=>r[colKey]))];if(keys.length>80)throw Error('LIMIT');const groups=new Map();for(const r of rows){const a=r[rowKey],b=r[colKey];if(!groups.has(a))groups.set(a,new Map());const cells=groups.get(a);if(!cells.has(b))cells.set(b,[]);cells.get(b).push(r);}return{keys,rows:[...groups].map(([key,cells])=>({key,values:keys.map(k=>aggregate(cells.get(k)||[],val,fn))}))};}
export function correlation(rows,a,b){let pairs=rows.filter(r=>numeric(r[a])&&numeric(r[b]));if(pairs.length<2)return null;let x=describe(pairs.map(r=>r[a])).mean,y=describe(pairs.map(r=>r[b])).mean,n=0,dx=0,dy=0;for(const r of pairs){let u=r[a]-x,v=r[b]-y;n+=u*v;dx+=u*u;dy+=v*v;}return dx&&dy?Math.max(-1,Math.min(1,n/Math.sqrt(dx*dy))):null;}
export function histogram(rows,key,bins=10){let vals=rows.map(r=>r[key]).filter(numeric);if(!vals.length)return[];const s=describe(vals),width=(s.max-s.min)/bins||1;let result=Array.from({length:s.min===s.max?1:bins},(_,i)=>({key:s.min+i*width,end:s.min+(i+1)*width,value:0}));for(const v of vals)result[Math.min(result.length-1,Math.floor((v-s.min)/width))].value++;return result;}
export function csv(rows,cols=columns(rows)){const escape=v=>{let s=missing(v)?'':String(v);if(typeof v==='string'&&/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};return '\uFEFF'+[cols.map(escape).join(','),...rows.map(r=>cols.map(c=>escape(r[c])).join(','))].join('\r\n');}
